 .btn:hover>span[aria-hidden]{transform:translate(3px,-3px)}
 .filter:hover{transform:translateY(-2px)}
}
@media(max-width:900px){
 .motion-ready .navlinks.open{animation:navari-drawer-in 280ms cubic-bezier(.22,1,.36,1) both}
 .motion-ready .menu:not([hidden]){animation:navari-detail-in 200ms ease}
}
@keyframes navari-draw{from{transform:scaleX(0) rotate(-1deg)}to{transform:scaleX(1) rotate(0)}}
@keyframes navari-menu-in{from{opacity:.2;transform:translateY(-8px)}to{opacity:1;transform:translateY(0)}}
@keyframes navari-drawer-in{from{opacity:.3;transform:translateX(28px)}to{opacity:1;transform:translateX(0)}}
@keyframes navari-detail-in{from{opacity:.2;transform:translateY(-5px)}to{opacity:1;transform:translateY(0)}}
