    const selector = [
      '.hero .eyebrow','.hero h1','.hero .intro','.hero .actions',
      '.hero-footnote','.ribbon-item','.workspace',
      '.page-hero .eyebrow','.page-hero h1','.page-hero .intro',
      '.section-top','.section > .wrap > h2','.section > .wrap > .eyebrow',
      '.featured-story','.archive-top','.app-card','.trust-item','.pillar','.step','.story-card','.feature',
      '.split > div','.contact-info','.consultation','.cta-inner > div','.faq details'
    ].join(',');
    const targets = [...document.querySelectorAll(selector)];
    targets.forEach(element => element.setAttribute('data-motion',''));
    const observer = 'IntersectionObserver' in window ? new IntersectionObserver(entries => {
      entries.forEach(entry => {
        if (!entry.isIntersecting) return;
        observer.unobserve(entry.target);
        if (seen.has(entry.target)) return;
        enter(entry.target, delayInGroup(entry.target));
        if (entry.target === workspace) animateWorkspace();
      });
    }, {threshold:0.08, rootMargin:'0px 0px -24px 0px'}) : null;
    const applyPreference = () => {
      root.classList.toggle('motion-ready', !preference.matches);
      if (preference.matches) {
        active.forEach(animation => animation.cancel());
        observer?.disconnect();
      } else {
        targets.forEach(element => {
          if (seen.has(element)) return;
          if (observer) observer.observe(element);
          else if (inView(element)) enter(element);
        });
      }
    };
    preference.addEventListener('change', applyPreference);
    applyPreference();
    // Reintroduce matching results when the visitor changes a filter.
    document.addEventListener('navari:filter', event => {
      [...event.target.querySelectorAll('.app-card:not([hidden]),.story-card:not([hidden])')]
        .filter(inView).forEach((element,index) => {
          observer?.unobserve(element);
          enter(element,Math.min(index,3)*55);
        });
    });
    // Keyboard focus and hidden tabs immediately settle ongoing motion.
    document.addEventListener('focusin', event => {
      // Pointer focus must not move a link between mouse-down and mouse-up.
      if (!event.target.matches(':focus-visible')) return;
      active.forEach(animation => {
        if (animation.effect?.target?.contains(event.target)) animation.cancel();
      });
    });
    document.addEventListener('visibilitychange', () => {
      if (document.hidden) active.forEach(animation => animation.cancel());
    });
    const header = document.querySelector('.header');
    let frame;
    const updateHeader = () => {
      frame = null;
      header?.classList.toggle('is-scrolled', scrollY > 24);
    };
    window.addEventListener('scroll', () => {
      if (!frame) frame = requestAnimationFrame(updateHeader);
    }, {passive:true});
    updateHeader();
  };
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded',init,{once:true});
  else init();
})();

/* Searchable, addressable archive. With no JavaScript, every story remains visible. */
(() => {
  const init = () => {
    const archive = document.querySelector('[data-story-archive]');
    if (!archive) return;
    const cards = [...archive.querySelectorAll('[data-story]')];
    const filters = [...archive.querySelectorAll('[data-archive-filter]')];
    const search = archive.querySelector('[name="story-search"]');
    const status = archive.querySelector('[data-archive-status]');
    const empty = archive.querySelector('.archive-empty');
    const pagination = archive.querySelector('.archive-pagination');
    const numbers = archive.querySelector('[data-page-numbers]');
    const previous = archive.querySelector('[data-page-previous]');
    const next = archive.querySelector('[data-page-next]');
    const categories = new Set(filters.map(button => button.dataset.archiveFilter));
    const pageSize = 6;
    const normalized = value => value.normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
    const indexed = new Map(cards.map(card => [card, normalized(card.dataset.search)]));
    let state;
    let inputTimer;
    const readState = () => {
      const params = new URLSearchParams(location.search);
      const hashCategory = {'#customer-stories':'customer','#news':'company'}[location.hash];
      const category = params.get('category') || hashCategory || 'all';
      return {category:categories.has(category)?category:'all',query:(params.get('q') || '').slice(0,200),page:Math.max(1,parseInt(params.get('page'),10)||1)};
    };
    const updateURL = method => {
      const url = new URL(location.href);
      ['category','q','page'].forEach(key => url.searchParams.delete(key));
      if (state.category !== 'all') url.searchParams.set('category',state.category);
      if (state.query) url.searchParams.set('q',state.query);
      if (state.page > 1) url.searchParams.set('page',String(state.page));
      url.hash = 'archive';
      if (url.href !== location.href) history[method+'State'](null,'',url);
    };
    const render = (focus = false) => {
      const terms = normalized(state.query.trim()).split(/\s+/).filter(Boolean);
      const matching = cards.filter(card => (state.category === 'all' || card.dataset.story === state.category) && terms.every(term => indexed.get(card).includes(term)));
      const pageCount = Math.max(1,Math.ceil(matching.length/pageSize));
      state.page = Math.min(state.page,pageCount);
      const start = (state.page-1)*pageSize;
      const visible = new Set(matching.slice(start,start+pageSize));
      cards.forEach(card => {card.hidden = !visible.has(card);});
      filters.forEach(button => button.setAttribute('aria-pressed',String(button.dataset.archiveFilter === state.category)));
      search.value = state.query;
      status.textContent = matching.length ? `Showing ${start+1}–${Math.min(start+pageSize,matching.length)} of ${matching.length} stories` : 'No stories match your search';
      empty.hidden = matching.length > 0;
      pagination.hidden = pageCount <= 1;
      previous.disabled = state.page <= 1;
      next.disabled = state.page >= pageCount;
      numbers.replaceChildren();
      for (let page=1; page<=pageCount; page++) {
        const button = document.createElement('button');
        button.type = 'button';button.textContent = String(page);button.dataset.page = String(page);
        button.setAttribute('aria-label',`Page ${page}`);
        if (page === state.page) button.setAttribute('aria-current','page');
        numbers.append(button);
      }
      if (focus) {
        archive.querySelector('#archive-heading').focus({preventScroll:true});
        archive.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});
      }
      archive.dispatchEvent(new CustomEvent('navari:filter',{bubbles:true}));
    };
    const navigate = page => {
      clearTimeout(inputTimer);
      state.query = search.value;state.page = page;
      render(true);
      updateURL('push');
    };
    filters.forEach(button => button.addEventListener('click', () => {
      clearTimeout(inputTimer);
      state.query = search.value;state.category = button.dataset.archiveFilter;state.page = 1;
      render();updateURL('push');
    }));
    search.addEventListener('input', () => {
      clearTimeout(inputTimer);
      inputTimer = setTimeout(() => {
        state.query = search.value;state.page = 1;render();updateURL('replace');
      },200);
    });
    search.addEventListener('keydown', event => {
      if (event.key === 'Enter') {
        event.preventDefault();clearTimeout(inputTimer);state.query=search.value;state.page=1;render();updateURL('replace');
      }
    });
    archive.querySelector('[data-reset-archive]').addEventListener('click', () => {
      clearTimeout(inputTimer);state={category:'all',query:'',page:1};render();updateURL('push');search.focus();
    });
    numbers.addEventListener('click', event => {
      const button = event.target.closest('[data-page]');
      if (button) navigate(Number(button.dataset.page));
    });
    previous.addEventListener('click', () => navigate(state.page-1));
    next.addEventListener('click', () => navigate(state.page+1));
    const restore = () => {clearTimeout(inputTimer);state=readState();render();};
    window.addEventListener('popstate',restore);
    window.addEventListener('hashchange',restore);
    state=readState();
    render();
    archive.querySelector('.archive-controls').hidden=false;
  };
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded',init,{once:true});
  else init();
})();

/* Optional reading tools. Article text, contents and source links work without JS. */
(() => {
  const init = () => {
    const article = document.querySelector('[data-article]');
    if (!article) return;
    const copy = article.querySelector('[data-copy-article]');
    const message = article.querySelector('[data-share-status]');
    if (navigator.clipboard?.writeText) {
      copy.hidden = false;
      copy.addEventListener('click', async () => {
        try {
          const url = new URL(location.href);url.hash='';url.search='';
          await navigator.clipboard.writeText(url.href);
          message.textContent='Article link copied.';
          copy.textContent='Link copied ✓';
        } catch {message.textContent='Could not copy the link. Copy the address from your browser instead.';}
      });
    }
    const body = article.querySelector('[data-article-content]');
    const progress = document.querySelector('[data-reading-progress]');
    let frame;
    const updateProgress = () => {
      frame=null;
      const rect=body.getBoundingClientRect();
      const start=scrollY+rect.top-innerHeight*.25;
      const range=Math.max(1,rect.height-innerHeight*.5);
      const value=Math.max(0,Math.min(1,(scrollY-start)/range));
      progress.style.transform=`scaleX(${value})`;
    };
    window.addEventListener('scroll',()=>{if(!frame)frame=requestAnimationFrame(updateProgress);},{passive:true});
    window.addEventListener('resize',updateProgress);updateProgress();
    if ('IntersectionObserver' in window) {
      const links=[...article.querySelectorAll('.article-sidebar nav a')];
      const observer=new IntersectionObserver(entries=>{
        const visible=entries.filter(entry=>entry.isIntersecting).sort((a,b)=>a.boundingClientRect.top-b.boundingClientRect.top);
        if(!visible.length)return;
        links.forEach(link=>{
          if(link.hash==='#'+visible[0].target.id)link.setAttribute('aria-current','location');
          else link.removeAttribute('aria-current');
        });
      },{rootMargin:'-15% 0px -50% 0px',threshold:0});
      article.querySelectorAll('.article-chapter,.article-media').forEach(section=>observer.observe(section));
    }
    article.querySelectorAll('[data-article-media]').forEach(shell=>{
      const button=shell.querySelector('[data-load-media]');
      const mount=shell.querySelector('.media-mount');
      const source=new URL(shell.dataset.src);
      const video=shell.dataset.kind==='video'&&source.origin==='https://www.youtube-nocookie.com'&&/^\/embed\/[A-Za-z0-9_-]{11}$/.test(source.pathname);
      const isDocument=shell.dataset.kind==='document'&&source.origin==='https://navari.co.ke'&&source.pathname.startsWith('/wp-content/uploads/')&&source.pathname.endsWith('.pdf');
      if(!video&&!isDocument)return;
      button.hidden=false;
      button.addEventListener('click',()=>{
        button.disabled=true;
        const iframe=window.document.createElement('iframe');
        iframe.src=source.href;iframe.title=shell.dataset.title;
        iframe.referrerPolicy='strict-origin-when-cross-origin';
        if(video){iframe.allow='encrypted-media; picture-in-picture; fullscreen';iframe.allowFullscreen=true;}
        iframe.addEventListener('error',()=>{shell.parentElement.querySelector('.media-error').hidden=false;});
        mount.replaceChildren(iframe);mount.hidden=false;
        shell.querySelector('.media-cover').hidden=true;
        iframe.setAttribute('tabindex','0');iframe.focus();
      },{once:true});
    });
  };
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});
  else init();
})();
